-- Dumping data for table `jurnal_siswa_tidak_hadir`
--

-- Data tabel `jurnal_siswa_tidak_hadir` dihapus semua karena id_siswa (72, 85, 86, 89, 96, 320, 80, 104)
-- merujuk siswa yang tidak ada di tabel siswa pada dump ini, sehingga foreign key
-- jurnal_siswa_tidak_hadir_ibfk_2 dapat valid saat import.

--
-- Triggers `jurnal_siswa_tidak_hadir`
--
DELIMITER $$
CREATE TRIGGER `trg_hitung_hadir_delete` AFTER DELETE ON `jurnal_siswa_tidak_hadir` FOR EACH ROW BEGIN
    UPDATE jurnal_kelas jk
    SET jumlah_hadir = (
        SELECT COUNT(*) FROM siswa s
        JOIN jadwal_mengajar jm ON jm.id_kelas = s.id_kelas
        WHERE jm.id_jadwal = jk.id_jadwal AND s.is_aktif = 1
    ) - (
        SELECT COUNT(*) FROM jurnal_siswa_tidak_hadir j
        WHERE j.id_jurnal = OLD.id_jurnal
    )
    WHERE jk.id_jurnal = OLD.id_jurnal;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_hitung_hadir_insert` AFTER INSERT ON `jurnal_siswa_tidak_hadir` FOR EACH ROW BEGIN
    UPDATE jurnal_kelas jk
    SET jumlah_hadir = (
        SELECT COUNT(*) FROM siswa s
        JOIN jadwal_mengajar jm ON jm.id_kelas = s.id_kelas
        WHERE jm.id_jadwal = jk.id_jadwal AND s.is_aktif = 1
    ) - (
        SELECT COUNT(*) FROM jurnal_siswa_tidak_hadir j
        WHERE j.id_jurnal = NEW.id_jurnal
    )
    WHERE jk.id_jurnal = NEW.id_jurnal;
END
$$
